"""Offline reader repair. Reuse saved AI/local data; no API or Tally requests."""
from pathlib import Path
from datetime import datetime
import ast,base64,hashlib,json,zlib,shutil,sys,re,subprocess

DATA=''


def install(root):
    folder=root/'Automation'/'Common_Rules'
    if not folder.is_dir():folder=root/'Common_Rules'
    changes=[]
    sha=lambda s:hashlib.sha256(s.encode('utf-8')).hexdigest()
    for item in json.loads(zlib.decompress(base64.b64decode(DATA))):
        path=folder/item['name']
        original=path.read_bytes() if path.exists() else None
        if original is not None:
            old=original.decode('utf-8-sig').replace('\r\n','\n')
            if sha(old)==sha(item['text']):continue
            if sha(old) not in item['before']:raise SystemExit('Different reader source; nothing changed: '+str(path))
        elif not item.get('create'):
            raise SystemExit('Reader source missing; nothing changed: '+str(path))
        ast.parse(item['text'],filename=str(path))
        changes.append((path,original,item['text']))
    if changes:
        backup=root/'.invoice_app'/'code_backups'/datetime.now().strftime('before_reading_fix_%Y%m%d_%H%M%S_%f')
        for path,original,text in changes:
            if original is not None:
                target=backup/path.relative_to(root);target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(original)
        try:
            for path,original,text in changes:path.write_text(text,encoding='utf-8',newline='\n')
        except Exception:
            for path,original,text in changes:
                if original is None:path.unlink(missing_ok=True)
                else:path.write_bytes(original)
            raise
        print('Reading fix installed. Backup: '+str(backup))
    else:print('Reading fix already installed.')
    return folder.parent


def main():
    root=Path(__file__).resolve().parent
    package=install(root)
    if '--install-only' in sys.argv:return
    # Use the reader's existing dependencies rather than installing packages
    # into whichever global Python the Windows py launcher selected.
    interpreters=[package/'.venv'/'Scripts'/'python.exe',root/'.venv'/'Scripts'/'python.exe']
    interpreter=next((p for p in interpreters if p.is_file()),None)
    if interpreter is not None and interpreter.resolve()!=Path(sys.executable).resolve():
        print('Using the reader Python environment for the offline repair.',flush=True)
        raise SystemExit(subprocess.run([str(interpreter),str(Path(__file__).resolve())],cwd=root).returncode)
    sys.path.insert(0,str(package))
    from Common_Rules.desktop import inspect_sources,process_sources
    from Common_Rules.gemini_batch import retained_result
    from Common_Rules.tally_review_export import enable
    clients=[p.name for p in root.iterdir() if p.is_dir() and re.sub(r'\s+','',p.name).casefold() in {'client17','client32'}]
    if not clients:
        print('No client 17/32 folders found here. Select the invoice root in the reader.');return
    results=[]
    for client in clients:
        print('Repairing saved/local reading and complete XML for '+client+'...')
        try:
            records=inspect_sources(root,[client],True,True)
            retained=sum(retained_result(root,record) is not None for record in records if record.get('digest'))
            enable(root,client)
            rows=process_sources(root,True,[client],True)
            prepared=sum(bool(row.get('output_path')) and not row.get('errors') for row in rows)
            entry={'client':client,'invoices':len(rows),'saved_ai_reused':retained,'xml_prepared':prepared,
                   'invoices_detail':[{'number':r['invoice'].get('number'),'date':r['invoice'].get('date'),
                    'buyer':r['invoice'].get('buyer_name'),'total':r['invoice'].get('total'),
                    'item_count':len(r['invoice'].get('items',[])),'errors':r.get('errors',[]),
                    'warnings':r.get('tally_review_warnings',[]),'output_path':r.get('output_path')} for r in rows]}
            results.append(entry)
            print(client+': '+str(len(rows))+' invoices; '+str(retained)+' saved AI reads reused; '+str(prepared)+' XML vouchers prepared.')
        except Exception as exc:
            results.append({'client':client,'error':str(exc)})
            print(client+': repair could not finish; details saved.')
    path=root/'.invoice_app'/'Reading_Fix_Result.json';path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(json.dumps({'no_ai_requests':True,'no_tally_imports':True,'results':results},indent=2,ensure_ascii=False),encoding='utf-8')
    print('Result: '+str(path))
    print('No new AI requests or Tally imports sent. Import ALL code unchanged.')
    print('Restart Python reader. Rebuild EXE if used. Existing approved corrections/history preserved.')


if __name__=='__main__':main()
